using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Build the chat client through MEAI -------------------------------------

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ------------------------------------------------------------

var notebook = new Notebook();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearchAsync(query),
        "web_search",
        "Searches the web for the given query and returns a list of result snippets."),

    AIFunctionFactory.Create(
        ([Description("Title for the note")] string title,
         [Description("Content of the note")] string content) =>
        {
            notebook.Add(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Saves a research note with a title and content."),

    AIFunctionFactory.Create(
        () => notebook.GetAllNotes(),
        "get_notes",
        "Returns all saved research notes."),
};

// --- Create the agent --------------------------------------------------------

var agent = new ChatClientAgent("ResearchAgent", chatClient)
{
    Instructions = """
        You are a research assistant. When given a topic:
        1. Use web_search to find relevant information (2-4 searches with varied queries).
        2. Use save_note to record key findings from each search.
        3. After gathering enough information, use get_notes to review everything.
        4. Provide a concise, well-structured summary with the key findings.
        Always cite your sources.
        """,
};

// --- Run the agent -----------------------------------------------------------

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and summarize your findings: {topic}"),
};

var runOptions = new AgentRunOptions
{
    MaximumIterations = 10,
    Tools = tools,
};

await foreach (var update in agent.RunStreamingAsync(messages, runOptions))
{
    foreach (var content in update.Contents)
    {
        if (content is TextContent text)
        {
            Console.Write(text.Text);
        }
    }
}

Console.WriteLine();

