 IChatClient chatClient = new ChatClientBuilder(innerClient)
     .UseFunctionInvocation()
     .Build();

 // --- Create the agent --------------------------------------------------------

 var agent = new ChatClientAgent(
     chatClient: chatClient,
     instructions: """
         You are a research assistant. When given a topic:
         1. Use web_search to find relevant information (2-4 searches with varied queries).
         2. Use save_note to record key findings from each search.
         3. After gathering enough information, use get_notes to review everything.
         4. Provide a concise, well-structured summary with the key findings.
         Always cite your sources.
         """,
     name: "ResearchAgent",
     tools: tools);

 // --- Run the agent -----------------------------------------------------------

 var topic = args.Length > 0
     ? string.Join(' ', args)
     : PromptForTopic();

 Console.WriteLine($"\n🔍 Researching: {topic}\n");

 var session = await agent.CreateSessionAsync();
 var response = await agent.RunAsync(
     $"Research the following topic and summarize your findings: {topic}",
     session);

 foreach (var message in response.Messages)
 {
     if (message.Role == ChatRole.Assistant)
     {
         foreach (var content in message.Contents)
         {
             if (content is TextContent text)
             {
                 Console.Write(text.Text);
             }
         }
     }
 }

 Console.WriteLine();

 // --- Helpers -----------------------------------------------------------------

 static string PromptForTopic()
 {
     Console.Write("Enter a research topic: ");
     var topic = Console.ReadLine()?.Trim();
     return string.IsNullOrWhiteSpace(topic)
         ? throw new InvalidOperationException("A research topic is required.")
         : topic;
 }

 static async Task<string> WebSearchAsync(string query)
 {
     Console.WriteLine($"  🌐 Searching: {query}");

     using var http = new HttpClient();
     http.DefaultRequestHeaders.UserAgent.ParseAdd(
         "ResearchAgent/1.0 (compatible; bot)");

     try
     {
         // Use DuckDuckGo Instant Answer API (no key required)
         var encoded = Uri.EscapeDataString(query);
         var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
         var json = await http.GetStringAsync(url);
         var doc = JsonDocument.Parse(json);
         var root = doc.RootElement;

         var sb = new StringBuilder();
         sb.AppendLine($"Search results for: {query}\n");

         // Abstract / main answer
         var abstractText = root.GetProperty("AbstractText").GetString();
         if (!string.IsNullOrWhiteSpace(abstractText))
         {
             var source = root.GetProperty("AbstractSource").GetString();
             var abstractUrl = root.GetProperty("AbstractURL").GetString();
             sb.AppendLine($"## {source}");
             sb.AppendLine(abstractText);
             sb.AppendLine($"Source: {abstractUrl}\n");
         }

         // Related topics
         if (root.TryGetProperty("RelatedTopics", out var topics))
         {
             var count = 0;
             foreach (var topic in topics.EnumerateArray())
             {
                 if (count >= 5) break;
                 var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                 var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                 if (!string.IsNullOrWhiteSpace(text))
                 {
                     sb.AppendLine($"- {text}");
                     if (!string.IsNullOrWhiteSpace(firstUrl))
                         sb.AppendLine($"  Source: {firstUrl}");
                     count++;
                 }
             }
         }

         var result = sb.ToString().Trim();
         return result.Length > 100 ? result : $"No detailed results found for \"{query}\". Try a more specific query.";
     }
     catch (Exception ex)
     {
         return $"Search failed for \"{query}\": {ex.Message}";
     }
 }

 // --- Notebook ----------------------------------------------------------------

 sealed class Notebook
 {
     private readonly List<(string Title, string Content)> _notes = [];

     public void Add(string title, string content) => _notes.Add((title, content));

     public string GetAllNotes()
     {
         if (_notes.Count == 0) return "No notes saved yet.";

         var sb = new StringBuilder();
         for (var i = 0; i < _notes.Count; i++)
         {
             sb.AppendLine($"### Note {i + 1}: {_notes[i].Title}");
             sb.AppendLine(_notes[i].Content);
             sb.AppendLine();
         }
         return sb.ToString();
     }
 }
